#!/bin/sh
# Installs the Atlantiraptor agent on Linux and connects it to your
# Atlantiraptor server.
#
# Generated by the Atlantiraptor console (Clients > Deploy a client) on
# {{.Generated}} for org "{{.OrgName}}". Server: {{.ServerURLs}}
#
# This script contains the server's client configuration: the server
# address, the CA certificate the agent trusts and the org's enrollment
# nonce. Anyone with this file can enroll a computer to your server, so
# share it only with the people who deploy agents.
#
# Installs /opt/atlantiraptor/atlantiraptor and the systemd service
# "atlantiraptor" (runs as root). The program is the file given with
# --binary, ./atlantiraptor in the current folder, or else downloaded from
# {{.ReleaseBase}}/Atlantiraptor-linux-<arch>
# and checked against that release's SHA256SUMS.
#
# Usage (as root):
#   sh install-atlantiraptor-linux.sh [--binary PATH] [--reinstall]
#   sh install-atlantiraptor-linux.sh --uninstall
set -eu

CONFIG_B64='{{.ConfigB64}}'
RELEASE_BASE='{{.ReleaseBase}}'
DIR=/opt/atlantiraptor
UNIT=/etc/systemd/system/atlantiraptor.service

BINARY=""
ACTION=install
REINSTALL=0
while [ $# -gt 0 ]; do
  case "$1" in
    --binary) BINARY="$2"; shift 2 ;;
    --reinstall) REINSTALL=1; shift ;;
    --uninstall) ACTION=uninstall; shift ;;
    *) echo "Unknown option: $1" >&2; exit 2 ;;
  esac
done

if [ "$(id -u)" != 0 ]; then
  echo "Run this as root (sudo)." >&2; exit 1
fi
if ! command -v systemctl >/dev/null 2>&1; then
  echo "This script needs systemd. On other systems run: atlantiraptor --config client.config.yaml client" >&2; exit 1
fi

uninstall() {
  systemctl disable --now atlantiraptor >/dev/null 2>&1 || true
  rm -f "$UNIT"
  systemctl daemon-reload
  rm -rf "$DIR"
}

if [ "$ACTION" = uninstall ]; then
  uninstall
  echo "Atlantiraptor is uninstalled."
  exit 0
fi

if [ -f "$UNIT" ] && [ "$REINSTALL" = 0 ]; then
  systemctl start atlantiraptor
  echo "Atlantiraptor is already installed and running. Use --reinstall to replace it."
  exit 0
fi

WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT

if [ -z "$BINARY" ] && [ -f ./atlantiraptor ]; then
  BINARY=./atlantiraptor
fi
if [ -z "$BINARY" ]; then
  case "$(uname -m)" in
    x86_64|amd64) ARCH=amd64 ;;
    aarch64|arm64) ARCH=arm64 ;;
    *) echo "No download for $(uname -m); pass --binary." >&2; exit 1 ;;
  esac
  NAME="Atlantiraptor-linux-$ARCH"
  fetch() {
    if command -v curl >/dev/null 2>&1; then curl -fsSL -o "$2" "$1"
    else wget -q -O "$2" "$1"; fi
  }
  echo "Downloading $RELEASE_BASE/$NAME"
  if ! fetch "$RELEASE_BASE/$NAME" "$WORK/atlantiraptor" || ! fetch "$RELEASE_BASE/SHA256SUMS" "$WORK/SHA256SUMS"; then
    echo "This release has no Linux program to download. Get the atlantiraptor program for Linux" >&2
    echo "from Atlant Security (or build it with 'make linux') and run this script again with" >&2
    echo "--binary /path/to/atlantiraptor, or put it in the current folder." >&2
    exit 1
  fi
  WANT=$(awk -v n="$NAME" '$2 == n || $2 == "*" n { print $1 }' "$WORK/SHA256SUMS")
  GOT=$(sha256sum "$WORK/atlantiraptor" | awk '{ print $1 }')
  if [ -z "$WANT" ] || [ "$WANT" != "$GOT" ]; then
    echo "The download does not match the release's SHA256SUMS; not installing." >&2; exit 1
  fi
  BINARY="$WORK/atlantiraptor"
fi

if [ -f "$UNIT" ]; then uninstall; fi

install -d -m 0700 "$DIR"
install -m 0700 "$BINARY" "$DIR/atlantiraptor"
echo "$CONFIG_B64" | base64 -d > "$DIR/client.config.yaml"
chmod 0600 "$DIR/client.config.yaml"

cat > "$UNIT" <<UNIT
[Unit]
Description=Atlantiraptor endpoint agent by Atlant Security
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
ExecStart=$DIR/atlantiraptor --config $DIR/client.config.yaml client --quiet
Restart=always
RestartSec=30
LimitNOFILE=20000

[Install]
WantedBy=multi-user.target
UNIT

systemctl daemon-reload
systemctl enable --now atlantiraptor
echo "Atlantiraptor is installed and running. The computer appears in the console under Clients within a minute."
